"""Rebuild reviewed, editorial reference content. No live-condition claims."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]/'Brackish'/'Resources'
species=[]
def fish(id,name,scientific,water,marks,habitat,tackle,source):
 species.append(dict(id=id,name=name,scientific=scientific,water=water,marks=marks.split('|'),habitat=habitat,tackle=tackle,source=source))
fish('striped-bass','Striped bass','Morone saxatilis','Saltwater','Long, dark horizontal stripes|Two distinct dorsal fins|Silvery sides and a powerful forked tail','An estuary and coastal fish that moves between salt and fresh water. Occurrence is seasonal; a map pin is not a catch forecast.','A medium saltwater spinning setup and a small swimming lure suit shore exploration. Non-offset circle hooks are required when fishing for striped bass with bait; check DEC details.','https://www.fisheries.noaa.gov/species/atlantic-striped-bass')
fish('bluefish','Bluefish','Pomatomus saltatrix','Saltwater','Blue-green back, silver sides|Large mouth with sharp teeth|Deeply forked tail','A schooling coastal predator. Young bluefish are often called snappers.','Use pliers and a bite-resistant leader. A casting spoon imitates small baitfish; match it to your rod rating. Keep fingers clear of the mouth.','https://www.fisheries.noaa.gov/species/bluefish')
fish('summer-flounder','Summer flounder','Paralichthys dentatus','Saltwater','Both eyes usually on the left side|Flattened, mottled body|Several eye-like spots on the upper side','Also called fluke. Often found on sandy or muddy coastal bottoms. Winter flounder is a different species.','A light bucktail or bait rig can work near the bottom. Use only enough weight to maintain contact and follow current size and season rules.','https://www.fisheries.noaa.gov/species/summer-flounder')
fish('scup','Scup','Stenotomus chrysops','Saltwater','Deep, compressed silver body|Small mouth and relatively small head|Long spiny dorsal fin','Also called porgy. A coastal bottom-feeding species associated with structure.','Small baited hooks and a simple bottom rig help present a small offering. A non-lead sinker reduces unnecessary lead use.','https://www.fisheries.noaa.gov/species/scup')
fish('black-sea-bass','Black sea bass','Centropristis striata','Saltwater','Dark body with pale scale centers|Long continuous dorsal fin|Larger males can have a raised forehead','A coastal fish associated with reefs, wrecks and other structure. Color changes with age and sex.','Use a small bait rig around structure with a leader suitable for abrasion. Check current seasons; they change during the year.','https://www.fisheries.noaa.gov/species/black-sea-bass')
fish('largemouth-bass','Largemouth bass','Micropterus salmoides','Freshwater','Upper jaw extends behind the eye|Dark horizontal band along the side|Notch between spiny and soft dorsal fins','A warmwater predator found around vegetation, cover and lake edges.','A weedless soft lure helps around aquatic plants. Use barbless hooks and non-lead weights in NYC park waters.','https://content.govdelivery.com/accounts/NYSDEC/bulletins/3a1112e')
fish('bluegill','Bluegill','Lepomis macrochirus','Freshwater','Dark flap at the rear of the gill cover|Deep oval body|Dark patch near the rear of the dorsal fin','A small sunfish often found near vegetation and shoreline cover.','A small barbless hook, a float and a short piece of worm provide a simple starting rig. Keep hooks small for the small mouth.','https://www.dnr.state.mn.us/fish/sunfish/biology.html')
fish('pumpkinseed','Pumpkinseed','Lepomis gibbosus','Freshwater','Orange-red spot at the edge of the dark ear flap|Wavy blue-green lines on the cheek|Speckled, deep-bodied sides','A colorful sunfish in quiet, vegetated fresh water. Juveniles and hybrids can be hard to separate from other sunfish.','Use a small barbless hook and float, as for bluegill. Check the cheek and ear flap before choosing a species.','https://www.dnr.state.mn.us/fish/sunfish/biology.html')
fish('black-crappie','Black crappie','Pomoxis nigromaculatus','Freshwater','Irregular dark mottling over silver sides|Deep body and large mouth|Usually seven or eight dorsal spines','A freshwater fish often associated with submerged cover. White crappie can look similar.','A tiny jig or small bait beneath a float is useful around cover. Cast gently and keep the hook barbless.','https://dec.ny.gov/things-to-do/freshwater-fishing/learn-to-fish/tips-skills/fishing-for-crappie')
fish('yellow-perch','Yellow perch','Perca flavescens','Freshwater','Dark vertical bars on yellow-green sides|Two separate dorsal fins|Orange or yellow lower fins','A schooling freshwater fish. Young fish may show paler colors than adults.','A small jig or a baited barbless hook beneath a float keeps the setup simple. Do not infer current abundance from historical survey records.','https://seagrant.sunysb.edu/nysportfishing/fishid.htm')
fish('common-carp','Common carp','Cyprinus carpio','Freshwater','Two pairs of barbels near the mouth|Large scales and a long dorsal fin|Thick body with a downward-facing mouth','An introduced freshwater fish. It can grow large in city lakes; goldfish generally lack its mouth barbels.','A sturdy spinning rod and a simple bottom presentation are practical. Use a soft landing net and keep a large fish supported.','https://dec.ny.gov/things-to-do/freshwater-fishing/places-to-fish/statewide-opportunities/carp')
fish('brown-bullhead','Brown bullhead','Ameiurus nebulosus','Freshwater','Whisker-like barbels around the mouth|Mottled brown body without scales|Tail squared or slightly rounded','A freshwater catfish found in several NYC park lakes. Other catfish can be difficult to separate from a single photograph.','A small bottom rig and pliers are helpful. Avoid the sharp fin spines; identify the fish in the water when possible.','https://dec.ny.gov/places/van-cortlandt-lake')
spots=[]
def spot(id,name,borough,water,lat,lon,subtitle,access,why,ids,source):
 spots.append(dict(id=id,name=name,borough=borough,water=water,latitude=lat,longitude=lon,subtitle=subtitle,access=access,why=why,speciesIDs=ids.split(','),source=source))
spot('gantry','Gantry Plaza','Queens','Saltwater',40.7441,-73.9601,'The city, seen from the water.','Use the designated fishing pier. Follow current park signs and avoid ferry operations. The pin marks the park vicinity, not a guaranteed open casting position.','A designated pier makes this a useful starting point for an East River shore trip. Coastal species below are regional possibilities, not a site-specific catch report.','striped-bass,bluefish,scup','https://parks.ny.gov/visit/state-parks/gantry-plaza-state-park')
spot('prospect','Prospect Park Lake','Brooklyn','Freshwater',40.6527,-73.9715,'A freshwater chapter in Brooklyn.','Fish from permitted shoreline areas; respect fences and refuge signs. Catch and release, barbless hooks and non-lead weights.','A practical lake choice for a light tackle outing. DEC documents bass and sunfish here; vegetation favors weedless presentations.','largemouth-bass,bluegill,pumpkinseed,black-crappie,common-carp','https://dec.ny.gov/places/prospect-park-lake')
spot('pier34','Pier 34','Manhattan','Saltwater',40.7221,-74.0139,'Two fingers reaching into the Hudson.','Use the public southern finger. The northern finger belongs to tunnel operations and is closed to the public. Follow posted fishing restrictions.','The park identifies the southern finger as a fishing place. A clear choice for a Manhattan estuary visit; regional species are possibilities, not predictions.','striped-bass,bluefish','https://hudsonriverpark.org/locations/pier-34/')
spot('van-cortlandt','Van Cortlandt Lake','Bronx','Freshwater',40.8840,-73.8945,'A quiet edge below the woods.','Shoreline includes grassy and steeper wooded areas. Choose a stable, permitted place to stand; the 1 train reaches 242nd Street nearby.','DEC records a diverse warmwater community. Suits a patient bass or panfish session with light tackle.','largemouth-bass,bluegill,black-crappie,yellow-perch,brown-bullhead','https://dec.ny.gov/places/van-cortlandt-lake')
spot('kissena','Kissena Lake','Queens','Freshwater',40.7473,-73.8054,'Small water. Plenty to observe.','Public shoreline in Kissena Park. Avoid discolored water or visible algal blooms and follow closures. Catch and release only.','A compact lake for a simple float rig. DEC’s 2022 survey documented bass, sunfish, bullhead and crappie; it is historical evidence.','largemouth-bass,bluegill,pumpkinseed,brown-bullhead,black-crappie','https://extapps.dec.ny.gov/docs/fish_marine_pdf/tb2kissena.pdf')
spot('clove','Clove Lake','Staten Island','Freshwater',40.6171,-74.1059,'An island lake beneath the trees.','Choose permitted shoreline at Clove Lakes Park. Respect other park users, posted access and vegetated edges.','A Staten Island freshwater option with bass and panfish listed by DEC. Bring a small float rig and a landing net.','largemouth-bass,bluegill,pumpkinseed,brown-bullhead','https://dec.ny.gov/places/clove-lake')
spot('steeplechase','Steeplechase Pier','Brooklyn','Saltwater',40.5700,-73.9853,'Where the boardwalk meets the Atlantic.','The fishing pier is off the boardwalk near West 19th Street. Exposed conditions can change quickly; check signs and keep clear of waves.','A designated shore-fishing destination on DEC’s NYC map. Suits an open-coast outing with saltwater gear; species are regional possibilities.','bluefish,striped-bass,summer-flounder,scup','https://dec.ny.gov/media/26796')
for name,value in [('species',species),('spots',spots)]:
 (root/(name+'.json')).write_text(json.dumps(value,indent=2)+'\n')
